"""Keep generated byte fixtures reproducible after source formatting."""

# SPDX-License-Identifier: GPL-3.0-or-later
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
import unittest


class GeneratedFixtures(unittest.TestCase):
    def test_roundtrip_and_changed_byte_rejection(self):
        root = Path(__file__).resolve().parents[2]
        fixtures = [
            ("tests/bios", "music_callbacks"),
            ("tests/gba/serial", "joybus_driver"),
            ("tests/gba/serial", "uart_driver"),
            ("tests/gba/serial", "cable_driver"),
        ]
        for directory, name in fixtures:
            with self.subTest(fixture=name), tempfile.TemporaryDirectory() as directory_copy:
                scratch = Path(directory_copy)
                generator = root / directory / f"generate_{name}.py"
                fixture = root / directory / (name.replace("_", "-") + ".inc")
                original = fixture.read_bytes()
                image = bytes(
                    int(value, 16) for value in re.findall(rb"0x([0-9A-Fa-f]{2})\b", original)
                )
                self.assertTrue(image)
                shutil.copyfile(generator, scratch / generator.name)
                shutil.copyfile(fixture, scratch / fixture.name)
                binary = scratch / "image.bin"
                binary.write_bytes(image)
                command = [sys.executable, str(scratch / generator.name), str(binary)]
                subprocess.run(command, check=True, capture_output=True, timeout=5)
                subprocess.run(command + ["--write"], check=True, capture_output=True, timeout=5)
                self.assertEqual((scratch / fixture.name).read_bytes(), original)
                changed = bytearray(image)
                changed[0] ^= 1
                binary.write_bytes(changed)
                result = subprocess.run(command, capture_output=True, timeout=5)
                self.assertNotEqual(result.returncode, 0)
                binary.write_bytes(image)
                changed_fixture = original.replace(b"0x", b"0X", 1)
                self.assertNotEqual(changed_fixture, original)
                (scratch / fixture.name).write_bytes(changed_fixture)
                result = subprocess.run(command, capture_output=True, timeout=5)
                self.assertNotEqual(result.returncode, 0)


if __name__ == "__main__":
    unittest.main()
